class NomFormaPago extends BaseNomFormaPago {

    /**
     * Obtener un listado de los datos de las formas de pago.
     * 
     * @param int       $inicio Inicio de la b�squeda.
     * @param int       $limite Limite maximo de la b�squeda.
	 *
     * @return array    Listado de los datos de las formas de pago.
     */
    public static function obtenerListadoFormasPago($inicio = 0, $limite = 1000) {

        //Devolviendo el listado de formas de pago en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomFormaPago')
                ->limit($limite)
                ->offset($inicio)
				->orderBy('denominacion')
                ->fetchArray():
        $query->from('NomFormaPago')
            ->orderBy('denominacion')
            ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de formas de pago.
     * 
     * @return int      Cantidad total de formas de pago.
     */
    public static function obtenerCantidadTotalFormasPago() {

        //Devolviendo la cantidad total de formas d epago.
        return Doctrine_Query::create()->select('COUNT(idformapago) AS cantidad')
                        ->from('NomFormaPago')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener la forma de pago dado el identificador.
     * 
     * @param $idform        	Identificador de la forma de pago.
	 *
     * @return NomFormaPago    	Objeto forma de pago (clase del dominio).
     */
    public static function obtenerObjFormaPagoDadoId($idform) {
        return Doctrine::getTable('NomFormaPago')->find($idform);
    }
    
	/**
     * Obtener si existe una forma de pago a partir de la denominaci�n.
     * 
	 * @param int $idforma    		Identificador de la forma de pago.
     * @param string $denom    	 	Denominaci�n de la forma de pago.
	 *
     * @return boolean    			Si existe la forma de pago.
     */
    public static function existeFormaPago($idforma, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idformapago) AS cantidad')
                        ->from('NomFormaPago')
						->where("denominacion ilike ?", $denom);
		if($idforma){
			$query->addWhere('idformapago <> ?', $idforma);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
/************************VER DESDE AQUI************************************/	
    public static function obtenerFormasPagoActivas() {
        //Devolviendo el listado de formas de pago activas en forma de arreglo.
        return Doctrine_Query::create()
				->select("idformapago, 'F-'||idformapago as id, idformapago as _id, denominacion, denominacion as text, fechainicio, fechafin, descripcion")
                ->from('NomFormaPago')
                ->where('fechafin is null or fechafin <= now()')
                ->fetchArray();
    }
    
    public static function existeDenominacionFormaPago($denominacion,$idformapago=null) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomFormaPago p')
                ->where("p.denominacion=? and p.idformapago<> ?", array($denominacion,
            $idformapago))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }

}
